// Pure Steam wishlist row semantics shared by the Codex collector (steam.mjs) and the Claude Code page
// script (generated by scripts/claude-code/build-page-script.mjs). Both functions MUST stay self-contained
// (no references to anything outside their own body) because they are serialized into a page, either by a
// host's evaluate call or by textual inlining. They only read the DOM; they never mutate it.

// Read the wishlist page: displayed count plus one entry per rendered row.
// A row is `complete` only when its app link text was found. Lazily rendered rows first show placeholder
// text (for example "MY CATEGORIES:"), and those must never replace or count as loaded rows.
export function snapshotWishlist() {
  if (location.protocol !== 'https:' || location.hostname !== 'store.steampowered.com' || !location.pathname.startsWith('/wishlist')) throw Error('Open the verified Steam Store wishlist');
  const count = document.body.innerText.match(/\b([\d,]+)\s+ITEMS\b/i);
  const rows = [];
  for (const h of document.querySelectorAll('[data-rfd-drag-handle-draggable-id^="WishlistItem-"]')) {
    const m = h.getAttribute('data-rfd-drag-handle-draggable-id').match(/^WishlistItem-(\d+)-(\d+)$/);
    const row = h.closest('.Panel');
    if (!m || !row) continue;
    const link = [...row.querySelectorAll('a[href*="/app/"]')].find(a => a.innerText.trim() && /\/app\/(\d+)/.exec(a.href)?.[1] === m[1] && !/^[\p{Sc}]/u.test(a.innerText.trim()));
    const raw = row.innerText.trim();
    rows.push({appid: Number(m[1]), rank: Number(m[2]) + 1, name: link?.innerText.trim() || raw.split('\n')[0] || null,
      pageText: raw, membershipSource: 'wishlist-row', complete: !!link});
  }
  const sort = [...document.querySelectorAll('button')].find(b => /^Sort by:/i.test(b.innerText.trim()));
  const box = document.querySelector?.('input[placeholder*="Search by name"]');
  return {expected: count ? Number(count[1].replace(/,/g, '')) : null, rows,
    view: {sort: sort ? sort.innerText.replace(/^Sort by:\s*/i, '').trim() : null,
      search: box ? (box.value.trim() ? 'active' : 'empty') : 'unknown', filters: 'unknown'}, reorderHandles: rows.length > 0};
}

// Merge one observed row into a Map keyed by AppID. A loaded row is never replaced by a placeholder,
// and a placeholder is replaced by the first loaded observation. Rows without a `complete` flag
// (older fixtures) are treated as loaded.
export function mergeWishlistRow(rows, row) {
  const next = {...row, complete: row.complete !== false}, old = rows.get(row.appid);
  if (!old || (!old.complete && next.complete)) rows.set(row.appid, next);
  return rows.get(row.appid);
}

// Records as stored in the envelope: only rows whose content actually loaded. An unresolved placeholder
// (blank or placeholder text, no app link) is omitted rather than stored with fabricated or empty fields; callers
// report its rank as missing. The evidence-only `complete` flag is not part of the data contract.
export function toWishlistRecords(rows) {
  return [...rows.values()].filter(r => r.complete).sort((a, b) => a.rank - b.rank).map(({complete, ...record}) => record);
}
